 "content": "def transform(grid):
    """Erase the two rows and two columns containing the 2x2 zero marker,
    except preserve cells colored 2."""
    h, w = len(grid), len(grid[0])
    marker = None
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0
                   for rr in (r, r + 1) for cc in (c, c + 1)):
                marker = (r, c)
                break
        if marker is not None:
            break
    if marker is None:
        raise ValueError("2x2 zero marker not found")
    r, c = marker
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if (i in (r, r + 1) or j in (c, c + 1)) and out[i][j] != 2:
                out[i][j] = 0
    return out
